### 2. The Retry Loop That Masks the Bug

**File:** `src/specialist/observability-sqlite.ts`, lines 46-71

```typescript
function withRetry<T>(operation: () => T, context: string): T {
  let lastError: Error | undefined;

  for (let attempt = 0; attempt < MAX_RETRY_ATTEMPTS; attempt++) {
    try {
      return operation();  // ← Throws "Cannot use a closed database"
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      const isRetryable = 
        lastError.message.includes('SQLITE_BUSY') ||
        lastError.message.includes('SQLITE_LOCKED') ||
        lastError.message.includes('database is locked') ||
        lastError.message.includes('database is busy');

      if (!isRetryable || attempt === MAX_RETRY_ATTEMPTS - 1) {
        break;  // ← "Cannot use a closed database" is NOT retryable, exits immediately
      }

      const delayMs = calculateRetryDelay(attempt);
      Bun.sleepSync(delayMs);
    }
  }

  throw new Error(`Failed after ${MAX_RETRY_ATTEMPTS} attempts (${context}): ${lastError?.message ?? 'unknown error'}`);
}
```

**Critical observation:** The error message "Cannot use a closed database" does NOT match any of the `isRetryable` conditions. This means the retry loop does NOT actually retry this error — it throws immediately after the first attempt. The "Failed after 5 attempts" message is misleading; it's actually failing on attempt 1.

