private async cleanup(): Promise<void> {
  const cleanupErrors: string[] = [];

  // Stop coordinator if active
  if (this.coordinatorJobId && this.coordinatorController) {
    try {
      await this.coordinatorController.stopJob(this.coordinatorJobId);
      await this.coordinatorController.waitForTerminal(this.coordinatorJobId, 5000);
    } catch (err) {
      cleanupErrors.push(`coordinator: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // Stop non-terminal members
  for (const [memberId, member] of this.members.entries()) {
    if (!TERMINAL_MEMBER_STATUSES.has(member.status) && member.jobId) {
      const controller = this.memberControllers.get(memberId);
      if (controller) {
        try {
          await controller.stopJob(member.jobId);
          await controller.waitForTerminal(member.jobId, 3000);
        } catch (err) {
          cleanupErrors.push(`member ${memberId}: ${err instanceof Error ? err.message : String(err)}`);
        }
      }
    }
  }

  // Clear controller references
  this.memberControllers.clear();
  this.coordinatorController = null;
  this.dispatchQueue = [];
  this.queuedActionKeys.clear();

  if (cleanupErrors.length > 0) {
