export function migrateToV2(db: BunDb): void {
  // Check current version
  const versionRow = db.query('SELECT version FROM schema_version ORDER BY version DESC LIMIT 1').get() as { version?: number } | undefined;
  const currentVersion = versionRow?.version ?? 1;

  if (currentVersion >= 2) return;  // Already migrated

  // Idempotent migration: add bead_id to specialist_jobs
  db.run(`
    CREATE TABLE IF NOT EXISTS specialist_jobs_v2 (
      job_id TEXT PRIMARY KEY,
      specialist TEXT NOT NULL,
      bead_id TEXT,
      worktree_column TEXT,
      status_json TEXT NOT NULL,
      updated_at_ms INTEGER NOT NULL,
      last_output TEXT
    );

    INSERT OR IGNORE INTO specialist_jobs_v2 
      (job_id, specialist, bead_id, worktree_column, status_json, updated_at_ms, last_output)
    SELECT 
      job_id, specialist, 
      JSON_EXTRACT(status_json, '$.bead_id') as bead_id,
      worktree_column, status_json, updated_at_ms, last_output
    FROM specialist_jobs;

    DROP TABLE IF EXISTS specialist_jobs;
    ALTER TABLE specialist_jobs_v2 RENAME TO specialist_jobs;

    INSERT OR REPLACE INTO schema_version (version, applied_at_ms) 
      VALUES (2, strftime('%s', 'now') * 1000);
  `);
}

