## Type Definitions Summary

### Specialist Entry

```ts
{
  name: string;
  scope: 'project' | 'user' | 'system';
  category: string;
  version: string;
  [key: string]: any;  // additional fields from .specialist.yaml
}
```

### Job Status

```ts
type JobStatus = 'running' | 'waiting' | 'done' | 'error' | 'unknown';
```

### Circuit Breaker State

```ts
type CircuitBreakerState = 'closed' | 'open' | 'half-open';
```

### Timeline Event

```ts
type TimelineEvent = {
  timestamp: number;  // unix milliseconds
  type: 'run_start' | 'meta' | 'tool' | 'text' | 'run_complete' | 'error';
  // ... event-specific fields vary by type
}
```

